mapper.select:
select id, activity_id, sku_id, seckill_price, total_stock,
       available_stock, limit_per_user, status,
       create_time, update_time, is_deleted
from seckill_sku
where activity_id = #{activityId}
  and id = #{seckillSkuId}
  and sku_id = #{skuId}
  and is_deleted = 0

mapper.update:
update seckill_sku
set available_stock = available_stock - 1,
    update_time = now()
where activity_id = #{activityId}
  and id = #{seckillSkuId}
  and sku_id = #{skuId}
  and status = 1
  and available_stock > 0
  and is_deleted = 0
